import hashlib
import hmac
import time
import os
import secrets
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple
import struct

# Secure token-bucket rate limiter for API gateway

SECRET_KEY = os.environ.get('HMAC_SECRET', secrets.token_hex(32))
MAX_REQUESTS_PER_WINDOW = 100
WINDOW_SIZE_SECONDS = 60
BAN_THRESHOLD = 500  # Total requests before temporary ban
BANNED_DURATION = 3600

@dataclass
class ClientState:
    request_count: int = 0
    window_start: float = 0.0
    total_requests: int = 0
    banned_until: float = 0.0
    auth_failures: int = 0

class RateLimiter:
    def __init__(self):
        self.clients: Dict[str, ClientState] = {}
        self._counter_max = (1 << 31) - 1  # Max signed 32-bit int

    def _get_client(self, client_id: str) -> ClientState:
        if client_id not in self.clients:
            self.clients[client_id] = ClientState(window_start=time.time())
        return self.clients[client_id]

    def _reset_window(self, state: ClientState) -> None:
        state.request_count = 0
        state.window_start = time.time()

    def _increment_counter(self, state: ClientState) -> int:
        """Increment request counter with overflow protection.
        Returns the new counter value, clamped to prevent overflow."""
        state.request_count += 1
        state.total_requests += 1
        # Clamp to max value to prevent any overflow issues
        if state.total_requests > self._counter_max:
            state.total_requests = self._counter_max
        return state.total_requests

    def check_rate_limit(self, client_id: str) -> Tuple[bool, str]:
        """Returns (allowed, reason). Thread-safe per-client check."""
        state = self._get_client(client_id)
        now = time.time()

        # Check if client is banned
        if state.banned_until > now:
            return (False, f"Banned until {state.banned_until}")

        # Reset window if expired
        if now - state.window_start >= WINDOW_SIZE_SECONDS:
            self._reset_window(state)

        # Increment and check
        total = self._increment_counter(state)

        # Check per-window limit
        if state.request_count > MAX_REQUESTS_PER_WINDOW:
            return (False, "Rate limit exceeded")

        # Check total request ban threshold
        if total >= BAN_THRESHOLD:
            state.banned_until = now + BANNED_DURATION
            return (False, "Temporary ban applied")

        return (True, "OK")


class SecureAPIGateway:
    def __init__(self):
        self.rate_limiter = RateLimiter()
        self._nonces: Dict[str, float] = {}  # nonce -> expiry time

    def _verify_request_signature(self, client_id: str, payload: bytes, 
                                   signature: str, timestamp: str, nonce: str) -> bool:
        """HMAC-SHA256 request authentication with replay protection."""
        now = time.time()

        # Validate timestamp freshness (5 minute window)
        try:
            req_time = float(timestamp)
        except (ValueError, TypeError):
            return False

        if abs(now - req_time) > 300:
            return False

        # Check nonce hasn't been used
        if nonce in self._nonces:
            return False

        # Validate nonce format
        if not nonce or len(nonce) != 32:
            return False

        # Compute expected signature
        msg = f"{client_id}:{timestamp}:{nonce}".encode() + payload
        expected = hmac.new(SECRET_KEY.encode(), msg, hashlib.sha256).hexdigest()

        if not hmac.compare_digest(expected, signature):
            return False

        # Store nonce with expiry
        self._nonces[nonce] = now + 600
        self._cleanup_nonces(now)

        return True

    def _cleanup_nonces(self, now: float) -> None:
        """Remove expired nonces to prevent memory growth."""
        expired = [n for n, exp in self._nonces.items() if exp <= now]
        for n in expired:
            del self._nonces[n]

    def handle_request(self, client_id: str, payload: bytes,
                       signature: str, timestamp: str, nonce: str) -> dict:
        """Main request handler with auth + rate limiting."""
        # Input validation
        if not client_id or not isinstance(client_id, str):
            return {"status": 400, "error": "Invalid client ID"}
        if len(client_id) > 64:
            return {"status": 400, "error": "Client ID too long"}

        # Rate limit check BEFORE auth to prevent auth-based DoS
        allowed, reason = self.rate_limiter.check_rate_limit(client_id)
        if not allowed:
            return {"status": 429, "error": reason}

        # Authenticate request
        if not self._verify_request_signature(client_id, payload, signature, timestamp, nonce):
            state = self.rate_limiter._get_client(client_id)
            state.auth_failures += 1
            # Auto-ban after 10 auth failures
            if state.auth_failures >= 10:
                state.banned_until = time.time() + BANNED_DURATION
            return {"status": 401, "error": "Authentication failed"}

        # Process the request
        return self._process_payload(client_id, payload)

    def _process_payload(self, client_id: str, payload: bytes) -> dict:
        """Process authenticated, rate-limited request."""
        if len(payload) > 1048576:  # 1MB max
            return {"status": 413, "error": "Payload too large"}

        content_hash = hashlib.sha256(payload).hexdigest()
        return {
            "status": 200,
            "client": client_id,
            "content_hash": content_hash,
            "processed_at": time.time()
        }
